from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Button, Color, Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up all devices.
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.Y, broadcast_channel=0, observe_channels=[1])
Left_motor = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right_Motor = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(Left_motor, Right_Motor, 62, 80)
Left_Attachment = Motor(Port.C, Direction.CLOCKWISE)
Right_Attachment = Motor(Port.D, Direction.CLOCKWISE)

# Initialize variables.
Current_Program = 0
Straight_Speed = 800
Turn_Speed = 500
Attachment_Speed = 600

async def mission__4():
    await wait(0)
    await drive_base.straight(250)
    await wait(10000)
    await drive_base.turn(90)
    await wait(10000)
    await drive_base.turn(90)
    await wait(10000)
    await drive_base.turn(90)
    await wait(10000)
    await drive_base.turn(90)
    await wait(10000)
    await drive_base.turn(90)
    await wait(10000)
    await drive_base.turn(90)
    await wait(10000)
    await drive_base.turn(90)
    await wait(10000)
    await drive_base.turn(90)
    await wait(10000)

async def Mission__1_():
    await wait(0)
    # key flip and removal attachment 1 - Block 11
    drive_base.reset(0, 0)
    await Left_Attachment.run_angle(200, 100, Stop.COAST)
    Left_Attachment.reset_angle(0)
    await Left_Attachment.run_angle(200, -80)
    await drive_base.straight(700)
    await drive_base.straight(-100)

async def mission__3():
    await wait(0)
    Right_Attachment.reset_angle(0)
    Left_Attachment.reset_angle(0)
    await drive_base.straight(800)
    await drive_base.turn(90)
    await drive_base.straight(340)
    await drive_base.turn(-90)
    await Left_Attachment.run_angle(700, 30, Stop.BRAKE)
    await Right_Attachment.run_angle(700, -30, Stop.BRAKE)
    await Left_Attachment.run_angle(700, 30, Stop.BRAKE)
    await Right_Attachment.run_angle(700, -30, Stop.BRAKE)

async def Mission__2():
    await wait(0)
    # top soil removel
    Right_Attachment.reset_angle(0)
    Left_Attachment.reset_angle(0)
    drive_base.reset(0, 0)
    await Right_Attachment.run_angle(500, -55)
    await Left_Attachment.run_angle(500, -90)
    Left_Attachment.reset_angle(0)
    Right_Attachment.reset_angle(0)
    await drive_base.straight(770)
    await drive_base.turn(-45)
    await drive_base.straight(-40)
    await Left_Attachment.run_angle(500, 55)
    await drive_base.straight(150)
    await drive_base.straight(-30)
    await multitask(
        Right_Attachment.run_angle(500, -90),
        Left_Attachment.run_angle(500, 80),
    )
    await drive_base.straight(40)

async def Mission_1():
    await wait(0)

async def Mission_3():
    await wait(0)

async def Mission_2():
    await wait(0)

async def Mission_4():
    await wait(0)

async def Mission_5():
    await wait(0)

async def mission__5():
    await wait(0)

async def Mission_6():
    await wait(0)

async def Mission_7():
    await wait(0)

async def my_task():
    await wait(0)

async def main1():
    global Current_Program
    prime_hub.system.set_stop_button(Button.BLUETOOTH)
    drive_base.settings(straight_speed=Straight_Speed)
    drive_base.use_gyro(True)
    drive_base.settings(turn_rate=Turn_Speed)
    # Main loop/interface that allows for selecting and launching programs
    while True:
        await wait(0)
        prime_hub.display.number(Current_Program)
        prime_hub.light.on(Color.GREEN)
        if Button.LEFT in prime_hub.buttons.pressed():
            # The left button goes back to the previous program
            Current_Program = Current_Program - 1
            await wait(200)
        elif Button.RIGHT in prime_hub.buttons.pressed():
            # The right button advances to the next program
            Current_Program = Current_Program + 1
            await wait(200)
        elif Button.CENTER in prime_hub.buttons.pressed():
            # The center button launches the currently selected program
            # Note you can also have this be the bluetooth button which is what
            # our FLL team did due to our unique robot design obstructing the
            # center button
            if Current_Program == -4:
                await mission__4()
            elif Current_Program == -3:
                await mission__3()
            elif Current_Program == -2:
                await Mission__2()
            elif Current_Program == -1:
                await Mission__1_()
            elif Current_Program == 1:
                await Mission_1()
            elif Current_Program == 2:
                await Mission_2()
            elif Current_Program == 3:
                await Mission_3()
            elif Current_Program == 4:
                await Mission_4()
            elif Current_Program == 5:
                await Mission_5()
            elif Current_Program == 6:
                await Mission_6()
            elif Current_Program == -5:
                await mission__5()
            elif Current_Program == 7:
                await Mission_7()
            else:
                pass
        else:
            await wait(10)

async def main2():
    pass


async def main():
    await multitask(main1(), main2())

run_task(main())